import pandas as pd
emp = pd.read_csv('/app/dataset/employees.csv')
ts = pd.read_csv('/app/dataset/timesheet.csv')

def pesel_checksum(pesel_str):
    if len(pesel_str) != 11 or not pesel_str.isdigit():
        return False
    weights = [1, 3, 7, 9, 1, 3, 7, 9, 1, 3]
    s = sum(int(pesel_str[i]) * weights[i] for i in range(10))
    ctrl = (10 - (s % 10)) % 10
    return ctrl == int(pesel_str[10])

for p in emp['PESEL'].astype(str):
    print(f'Emp PESEL {p}: valid_chk={pesel_checksum(p)}')

unknown = {'16102016795', '68011910138', '62020111425', '15720759071', '84731091580'}
for u in unknown:
    print(f'Unknown PESEL {u}: valid_chk={pesel_checksum(u)}')
"
